import itertools

def count_subsequences(seq, length):
    # We want to count subsequences (a_i, a_j, a_k) with a_j = a_i+1, a_k = a_j+1
    # Since the values are always consecutive, we can use DP or just iterate.
    # However, for small k, we can just use the simple way.
    count = 0
    for sub in itertools.combinations(seq, length):
        if all(sub[i+1] == sub[i] + 1 for i in range(length - 1)):
            count += 1
    return count

def solve_small_k(k):
    values = [0]*k + [1]*k + [2]*k + [3]*k
    max_m = 0
    for p in itertools.permutations(values):
        m = count_subsequences(p, 3)
        n = count_subsequences(p, 4)
        if n == 0:
            if m > max_m:
                max_m = m
    return max_m

for k in range(1, 6):
    print(f"k={k}: {solve_small_k(k)}")

def count_subsequences_proper(seq, max_val):
    dp = [[0]*(max_val+2) for _ in range(max_val+2)]
    for x in seq:
        v = x + 1
        dp[1][v] += 1
        for l in range(2, max_val+1):
            dp[l][v] += dp[l-1][v-1]

    # m is number of subsequences of length 3 (x, x+1, x+2)
    # n is number of subsequences of length 4 (x, x+1, x+2, x+3)
    m = sum(dp[3][v] for v in range(1, max_val+2))
    n = sum(dp[4][v] for v in range(1, max_val+2))
    return m, n

def solve_small_k_random_multi(k, num_values):
    values = []
    for v in range(num_values):
        values.extend([v]*k)
    max_m = 0
    import random
    for _ in range(200000):
        p = list(values)
        random.shuffle(p)
        m, n = count_subsequences_proper(p, num_values)
        if n == 0:
            if m > max_m:
                max_m = m
    return max_m

for nv in range(4, 9):
    print(f"num_values={nv}: {solve_small_k_random_multi(5, nv)}")
